bg=6
out=[[bg]*13 for _ in range(13)]
tiles={(1,1):1,(1,7):3,(7,1):7,(7,7):5}
masks={1:[[0,0,1],[1,1,1],[0,0,1]],3:[[0,1,1],[0,1,1],[1,0,0]],7:[[0,1,1],[1,1,0],[0,0,1]],5:[[0,1,1],[1,1,0],[0,1,1]]}
for (r0,c0),color in tiles.items():
    for r in range(5):
        for c in range(5): out[r0+r][c0+c]=color
    for r in range(3):
        for c in range(3):
            if masks[color][r][c]: out[r0+1+r][c0+1+c]=bg
print('\n'.join(' '.join(map(str,row)) for row in out))
print([len(r) for r in out])
